import os
import sys
import concurrent.futures
import shutil

def copy_file(source_path, dest_path):
    os.makedirs(os.path.dirname(dest_path), exist_ok=True)
    shutil.copy2(source_path, dest_path)

def main():
    if len(sys.argv) != 3:
        print("Usage: python copyfiles.py <dest_dir> <max_in_flight>")
        return

    dest_dir = sys.argv[1]
    max_in_flight = int(sys.argv[2])

    if max_in_flight < 1:
        print("<max_in_flight> must be at least 1.")
        return

    copy_operations = []

    for line in sys.stdin:
        line = line.strip()
        if line:
            source_path, dest_name = line.split('\t')
            dest_path = os.path.join(dest_dir, dest_name)
            copy_operations.append((source_path, dest_path))

    count = 0
    with concurrent.futures.ThreadPoolExecutor(max_workers=max_in_flight) as executor:
        futures = {executor.submit(copy_file, source, dest): (source, dest) for source, dest in copy_operations}
        for future in concurrent.futures.as_completed(futures):
            try:
                future.result()
                count += 1
            except Exception as e:
                print(f"Error copying file {futures[future][0]} to {futures[future][1]}: {e}")

    print(f"COPIED {count}")

if __name__ == '__main__':
    main()

import os
import sys
import threading
from queue import Queue

def copy_file(source, dest_dir, dest_name):
    dest_path = os.path.join(dest_dir, dest_name)
    os.makedirs(os.path.dirname(dest_path), exist_ok=True)
    with open(source, 'rb') as src, open(dest_path, 'wb') as dst:
        dst.write(src.read())

def worker(queue, max_in_flight, dest_dir):
    active = 0
    while True:
        if active >= max_in_flight:
            queue.join()
        if not queue.empty():
            source, dest_name = queue.get()
            try:
                copy_file(source, dest_dir, dest_name)
                queue.task_done()
                active += 1
            except Exception:
                queue.task_done()
                active -= 1
                continue
        else:
            queue.join()

def main():
    dest_dir = sys.argv[1]
    max_in_flight = int(sys.argv[2])
    queue = Queue()
    threads = []

    for _ in range(max_in_flight):
        t = threading.Thread(target=worker, args=(queue, max_in_flight, dest_dir))
        t.start()
        threads.append(t)

    for line in sys.stdin:
        if not line.strip():
            continue
        source, dest_name = line.strip().split('\t', 1)
        queue.put((source, dest_name))

    queue.join()
    for t in threads:
        t.join()

    print(f"COPIED {queue.qsize()}")

if __name__ == "__main__":
    main()
